using UnityEngine;using UnityEditor;using UnityEngine.UI;using IdleIntelligence.Runtime;
namespace IdleIntelligence.Editor {
 public static class CalmChrome {
  static void Line(Transform parent,string name,Vector2 min,Vector2 max,Vector2 size){var t=parent.Find(name);if(t==null)t=WorkshopUIFactory.Node(name,parent,typeof(Image),typeof(LayoutElement)).transform;var r=(RectTransform)t;r.anchorMin=min;r.anchorMax=max;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=Vector2.zero;r.sizeDelta=size;t.GetComponent<LayoutElement>().ignoreLayout=true;var image=t.GetComponent<Image>();image.color=GameTheme.Hex("294557");image.raycastTarget=false;}
  public static void Apply(Transform safe){var resources=safe.Find("Resources");var bar=resources.GetComponent<Image>();bar.sprite=null;bar.color=GameTheme.Hex("10202E");var height=resources.GetComponent<LayoutElement>();height.minHeight=height.preferredHeight=52;resources.GetComponent<HorizontalLayoutGroup>().spacing=0;int index=0;foreach(Transform cell in resources){if(!cell.name.StartsWith("ResourceCell"))continue;var face=cell.GetComponent<Image>();face.sprite=null;face.color=Color.clear;if(index++>0)Line(cell,"Separator",new Vector2(0,.23f),new Vector2(0,.77f),new Vector2(1,0));var name=cell.Find("ResourceName").GetComponent<Text>();name.fontSize=11;name.resizeTextMinSize=10;name.resizeTextMaxSize=11;var value=cell.GetComponentsInChildren<Text>()[0];value.resizeTextMinSize=12;value.resizeTextMaxSize=15;}
   Line(resources,"BottomRule",new Vector2(0,0),new Vector2(1,0),new Vector2(0,1));var nav=safe.Find("Tabs");var navFace=nav.GetComponent<Image>()??nav.gameObject.AddComponent<Image>();navFace.raycastTarget=false;navFace.sprite=null;navFace.color=GameTheme.Hex("10202E");nav.GetComponent<HorizontalLayoutGroup>().spacing=0;foreach(var button in nav.GetComponentsInChildren<Button>()){var face=button.GetComponent<Image>();face.sprite=null;face.type=Image.Type.Simple;face.color=Color.clear;var colors=button.colors;colors.normalColor=Color.white;colors.highlightedColor=Color.white;colors.pressedColor=GameTheme.Hex("9CD9DA");button.colors=colors;var icon=button.transform.Find("NavigationIcon").GetComponent<Image>();var ir=icon.rectTransform;ir.anchorMin=ir.anchorMax=new Vector2(.5f,.67f);ir.sizeDelta=new Vector2(28,28);ir.anchoredPosition=Vector2.zero;var text=button.GetComponentInChildren<Text>();text.resizeTextMinSize=10;text.resizeTextMaxSize=12;text.fontSize=12;var active=(RectTransform)button.transform.Find("ActiveLine");active.anchorMin=new Vector2(.24f,1);active.anchorMax=new Vector2(.76f,1);active.sizeDelta=new Vector2(0,3);active.anchoredPosition=new Vector2(0,-2);}
   Line(nav,"TopRule",new Vector2(0,1),new Vector2(1,1),new Vector2(0,1));
  }
 }
}
